with scored as (select *, sum(sqft) over (partition by region) as region_sum_sqft, last_value(region, true) over (partition by region order by opened_date, id rows between unbounded preceding and current row) as last_known_region, first_value(sqft) ignore nulls over (partition by region order by sqft, id rows between unbounded preceding and current row) as first_known_sqft, round(sqft / sum(sqft) over (partition by region), 4) as sqft_share, lag(sqft, 2) over (partition by city order by opened_date, id) as prev_sqft from stores) select region, city, round(avg(sqft_share), 2) as avg_sqft_share, sort_array(collect_set(city)) as city_list from scored group by region, city having avg_sqft_share < 0 order by region nulls first
